-- Migration 025: US team stints confirmed by the player's Wikipedia infobox (playing career)
-- Run in Supabase SQL Editor. One transaction. PURE ASCII (no player names in this file: names come from players).
-- Approved 12 Oct 2026 (review page "US Team Stints"): played_for_team facts at our NBA / NFL / MLB / NHL teams that
-- Wikidata lists, the infobox's PLAYING career shows, and we don't have. Offseason / practice-squad, coaching, draft-only
-- and not-in-infobox entries are left out. Stints that start in 2026 are in 026.
-- ABA and WHA years count for the franchises that joined the NBA / NHL (user rule): Nets, Pacers, Spurs (incl. Dallas /
-- Texas Chaparrals), Nuggets (incl. Denver Rockets); Oilers, Nordiques -> Avalanche, Whalers -> Hurricanes,
-- Winnipeg Jets (1972-96) -> Coyotes. Those rows have owner_method 'wikipedia infobox, ABA/WHA franchise history (025)'.
--   1986 rows 'wikipedia infobox + wikidata (025)', 156 rows 'wikipedia infobox, ABA/WHA franchise history (025)'
--   by sport: NBA 471, NFL 503, MLB 511, NHL 657
--   46 existing unowned rows get their owner; 2096 rows are inserted (174 under the article title).
-- Nothing is deleted. 0. GUARD first (clear message if already applied). 1. BACKUP of the adopted rows.

BEGIN;

DO $mig$
DECLARE n BIGINT;
BEGIN
  SELECT count(*) INTO n FROM player_facts WHERE owner_method IN ('wikipedia infobox + wikidata (025)', 'wikipedia infobox, ABA/WHA franchise history (025)');
  IF n > 0 OR to_regclass('public.backup_20261012_facts_025') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 025 is already applied (% rows with its owner_method). Nothing changed.', n;
  END IF;
  SELECT count(*) INTO n FROM player_facts WHERE id IN (515903, 1140517, 671444, 663366, 1007391, 679605, 678796, 694920, 952520, 696696, 657032, 691252, 665659, 682782, 887319, 909363, 668765, 720509, 1065324, 1086427, 538125, 1188910, 559767, 1246104, 1246425, 1257781, 1283125, 1279197, 578260, 583835, 584110, 587301, 590470, 611435, 615031, 619546, 621885, 622647, 629535, 651419, 730310, 733121, 733249, 732858, 727511, 760605) AND player_id IS NULL AND fact_type = 'played_for_team';
  IF n <> 46 THEN RAISE EXCEPTION '025 guard: expected 46 unowned rows to own, found %. Nothing changed.', n; END IF;
END $mig$;

