-- --- CHECKS (run after COMMIT, alone, in a fresh session; one row) ---------------------------------
SELECT
  (SELECT count(*) FROM backup_20261012_facts_025)                                                                         AS backup_rows,
  (SELECT count(*) FROM player_facts WHERE owner_method = 'wikipedia infobox + wikidata (025)')                                       AS rows_m1,
  (SELECT count(*) FROM player_facts WHERE owner_method = 'wikipedia infobox, ABA/WHA franchise history (025)')                                       AS rows_m2,
  (SELECT count(*) FROM player_facts WHERE owner_method IN ('wikipedia infobox + wikidata (025)', 'wikipedia infobox, ABA/WHA franchise history (025)') AND player_id IS NULL) AS unowned_new,
  (SELECT count(*) FROM (SELECT f.player_id, f.sport, f.fact_value FROM player_facts f WHERE f.fact_type = 'played_for_team'
     AND f.player_id IN (SELECT player_id FROM player_facts WHERE owner_method IN ('wikipedia infobox + wikidata (025)', 'wikipedia infobox, ABA/WHA franchise history (025)')) GROUP BY 1, 2, 3
     HAVING count(*) FILTER (WHERE owner_method IN ('wikipedia infobox + wikidata (025)', 'wikipedia infobox, ABA/WHA franchise history (025)')) > 0 AND count(*) > 1) d) AS doubled,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname = 'backup_20261012_facts_025')                              AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name = 'backup_20261012_facts_025' AND grantee IN ('anon', 'authenticated')) AS backup_browser_grants,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 8379467 AND f.sport = 'NFL' AND f.fact_type = 'played_for_team' AND f.fact_value = 'Falcons') AS matt_ryan_falcons,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 1738892 AND f.sport = 'NBA' AND f.fact_type = 'played_for_team' AND f.fact_value = 'Nuggets') AS haywood_nuggets_aba,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 1097163 AND f.sport = 'NHL' AND f.fact_type = 'played_for_team' AND f.fact_value = 'Oilers') AS fogolin_oilers,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 240940 AND f.sport = 'NBA' AND f.fact_type = 'played_for_team' AND f.fact_value = '76ers') AS lebron_76ers_held,
  (SELECT count(*) FROM player_facts WHERE owner_method IN ('wikipedia infobox + wikidata (025)', 'wikipedia infobox, ABA/WHA franchise history (025)') AND sport = 'NBA') AS nba_rows;
